inline VEPT::VEPT(const VEPT &o)
      : ID(o.ID),
        VEHICLE_CLASS_ID(o.VEHICLE_CLASS_ID),
        VEHICLE_TYPE_DESIGNATOR(o.VEHICLE_TYPE_DESIGNATOR),
        ENVIRONMENT(o.ENVIRONMENT),
        ENERGY_TYPE(o.ENERGY_TYPE),
        CAPACITY_VALUE(o.CAPACITY_VALUE),
        CAPACITY_UNITS(o.CAPACITY_UNITS),
        RESERVE_FRACTION(o.RESERVE_FRACTION),
        INTERPOLATION(o.INTERPOLATION),
        MAXIMUM_ENDURANCE_S(o.MAXIMUM_ENDURANCE_S),
        MAXIMUM_RANGE_M(o.MAXIMUM_RANGE_M),
        LOITER_SPEED_MPS(o.LOITER_SPEED_MPS),
        SERVICE_CEILING_M(o.SERVICE_CEILING_M),
        REFINES_ID(o.REFINES_ID),
        SOURCE((o.SOURCE) ? new VEPProvenanceT(*o.SOURCE) : nullptr) {
  PERFORMANCE_POINTS.reserve(o.PERFORMANCE_POINTS.size());
  for (const auto &PERFORMANCE_POINTS_ : o.PERFORMANCE_POINTS) { PERFORMANCE_POINTS.emplace_back((PERFORMANCE_POINTS_) ? new VEPPerformancePointT(*PERFORMANCE_POINTS_) : nullptr); }
  REPLENISHMENT.reserve(o.REPLENISHMENT.size());
  for (const auto &REPLENISHMENT_ : o.REPLENISHMENT) { REPLENISHMENT.emplace_back((REPLENISHMENT_) ? new VEPReplenishmentT(*REPLENISHMENT_) : nullptr); }
}

